&lt;li&gt;
&lt;p id=&quot;p-rc_a6dea2eb4a17e30a-73&quot; data-path-to-node=&quot;6,3,0&quot;&gt;&lt;span data-path-to-node=&quot;6,3,0,0&quot;&gt;Current Active Duty United States military member or Guard/Reserve component on active duty orders with 180 days or fewer remaining prior to your date of discharge and at least 180 continuous days of active service&lt;/span&gt;&lt;span data-path-to-node=&quot;6,3,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt; &lt;/p&gt;
