&lt;p id=&quot;p-rc_a6dea2eb4a17e30a-76&quot; data-path-to-node=&quot;8,2,0&quot;&gt;&lt;span data-path-to-node=&quot;8,2,0,0&quot;&gt;Experience with Hypervisors (VMware, Hyper-V, KVM) and authentication systems (SAML, LDAP, MS Active Directory)&lt;/span&gt;&lt;span data-path-to-node=&quot;8,2,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt; &lt;/p&gt;
